{
  "concepts": [
    {
      "conditions": [],
      "definition": "A Project Reference-Frame Basis is a Product-owned accepted declaration of the shared frame set for finite actors engaging one governed Product scope or outcome. It binds the exact Reference Frame Method and optional profile, admitting authorities and scopes, frame declarations and evaluation inventory, actor rules and capabilities, semantic/evaluation/operation/decision grants, result/conjunction/translation/coverage relations, activation triggers and invalidation law.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 830,
          "quote": "  + lifecycle activation triggers and invalidation law\n",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 830
        }
      ],
      "key": "project_reference_frame_basis",
      "label": "Project Reference-Frame Basis"
    },
    {
      "conditions": [],
      "definition": "Agent Frame Activation is an execution-scoped binding of one agent to an applicable frame declaration or active configuration, exact evaluation, subject, basis, evidence boundary and capability envelope. The durable Product Definition Overlay records the shared basis; a ticket or other authorized instruction carries the activation packet. Frames and actors are separate identities.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 864,
          "quote": "is the execution-scoped binding of one agent to an applicable\nframe declaration or active configuration, exact evaluation, subject, basis,\nevidence boundary, and capability envelope.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 862
        }
      ],
      "key": "agent_frame_activation",
      "label": "Agent Frame Activation"
    },
    {
      "conditions": [],
      "definition": "Build tenancy, owned here in urn:stdo:bounded-context:build-tenancy under a selected complete STDO basis, is the one-or-more realization relation from a common constitutional WHAT to independent project-owned HOW tenants. A build tenant is one realization; multi-build-tenancy means more than one. WHAT supplies requirements; tenant design supplies computational operations, composition, performers, effects, assumptions and observation bindings. The Tenant Registry is how.build_tenants; how.common binds an explicitly shared realization law.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 910,
          "quote": "A\n**build tenant** is one such realization. **Build tenancy** is the one-or-more\nrelation; one tenant is its singleton case and multi-build-tenancy begins when\nthe same `WHAT` has more than one independent realization.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FWHAT%2C%20HOW%2C%20And%20Work%20Carriers",
          "start_line": 907
        }
      ],
      "key": "build_tenancy",
      "label": "WHAT, HOW and build tenancy"
    },
    {
      "conditions": [],
      "definition": "The discovered definition set consists of stdo_*.json definitions recursively located inside a selected workspace, including its root and arbitrarily deep project roots. Explicit directed composition relates otherwise independent definitions using a target locator, expected stable definition identity, relation authority and non-empty governing contract references.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 970,
          "quote": "Tools discover `stdo_*.json` recursively within the selected workspace\nboundary. Discovery includes definitions at the workspace root and definitions\nat arbitrarily deep nested project roots.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FRecursive%20Discovery%20And%20Explicit%20Composition",
          "start_line": 968
        }
      ],
      "key": "discovered_definition_set",
      "label": "Recursive discovery and explicit composition"
    },
    {
      "conditions": [],
      "definition": "Semantic-resolution conformance concerns uniquely resolved uses and material collisions under an exact selected basis. A local positive case declares one context and exactly one concept; a cross-context positive case supplies a complete authorized relation. Frame, Owner, Product, Tenant and User are explicit collision cases with distinct context-dependent meanings.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1037,
          "quote": "A positive local case declares one context and resolves exactly one concept. A\npositive cross-context case supplies the complete authorized relation.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FSemantic-Resolution%20Conformance%20Cases",
          "start_line": 1036
        }
      ],
      "key": "semantic_resolution",
      "label": "Semantic-resolution conformance"
    },
    {
      "conditions": [],
      "definition": "STDO-SURFACE-001 describes a modularly authored but singularly authoritative constitution: one complete released method cut, one owning standard per law, and reference consumption by other standards. A released cut identifies its exact members, digests, review basis, human acceptance and immutable identity. Derived, evidential and authoring surfaces include compressions, templates, comments, candidate work, installed copies and mutable source.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1057,
          "quote": "The shared methodology is modular in authorship and singular in authority.\nEach law has one owning standard; other standards consume it by reference. The\nstandards become operative only as one complete released STDO version.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FOne%20Constitutional%20Surface%20And%20Version%20Boundary%20%28%60STDO-SURFACE-001%60%29",
          "start_line": 1055
        }
      ],
      "key": "released_method_constitution",
      "label": "Released method constitution"
    },
    {
      "conditions": [],
      "definition": "The constitutional chain runs Goals → Intent → Product Definition → Requirements → Design → Realisation → Observations → Projection → Delta → Scenarios → Gap Analysis → intake-selected re-entry or observation. Goals own current concerns; Intent purpose/direction; mutable Product Definition current realization, terms and end-state shape; Requirements invariant obligations; Design structural decisions, interfaces, carriers and topology; Realisation their concrete enactment; Observations bounded facts; Projection question-relevant views; Delta drift; Scenarios operational meaning; Gap Analysis insufficiency. ADRs are durable Design records, not an additional constitutional layer. GOALS.md carries a bounded work wave; PRODUCT.md bridges direction to decomposable obligations and is neither immutable release artifact nor installed product.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1108,
          "quote": "Goals → Intent → Product Definition → Requirements → Design → Realisation → Observations → Projection → Delta\n                                                                                       ↓\n                                                                                  Scenarios\n                                                                                       ↓\n                                                                                Gap Analysis\n                                                                                       ↓\n                                                                  Intake-selected re-entry or observation",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FConstitutional%20Chain",
          "start_line": 1102
        }
      ],
      "key": "constitutional_chain",
      "label": "Constitutional chain and carrier roles"
    },
    {
      "conditions": [],
      "definition": "A sprint is a bounded execution-control surface under existing constitutional authority, not another constitutional layer. It can batch and coordinate work, price proof cost and force close review. Deferred compliance is escrow; sprint close is forensic reconciliation of accumulated work and evidence.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1168,
          "quote": "A sprint is a bounded execution-control surface.\n\nIt is not a new layer in the constitutional chain.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSprint%20Execution%20Boundary",
          "start_line": 1166
        }
      ],
      "key": "sprint",
      "label": "Sprint execution boundary"
    },
    {
      "conditions": [],
      "definition": "The substrate-neutral ambiguity-governance context is urn:stdo:bounded-context:ambiguity-governance. Major ambiguity materially changes architecture, stack, Product boundary, execution/deployment admissibility, public contracts or downstream realization law; micro ambiguity is local choice within governed Design. Lawful Probabilistic Processing is bounded non-human ambiguity handling permitted by declared policy. Human Adjudication is explicit human judgment admitted by authority where policy or risk appetite requires it. Resolved, carried forward, escalated and blocked are handling annotations, distinct from claim verdicts.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1257,
          "quote": "- **major ambiguity**: ambiguity that materially changes architecture, stack,\n  product boundary, execution/deployment admissibility, public contract shape,\n  or other downstream realization law\n- **micro ambiguity**: local implementation choice that remains inside an\n  already-governed design boundary",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAmbiguity%20Governance%20Rule",
          "start_line": 1253
        }
      ],
      "key": "ambiguity_governance",
      "label": "Ambiguity governance and handling"
    },
    {
      "conditions": [],
      "definition": "Every material product, application, module, graph function, runtime/plugin/public/data surface or capability has an operational lifecycle: intent → requirement → build → assurance → release → deployment → live usage → observed telemetry → retirement. Lifecycle sufficiency is constitutional signal enabling downstream Design or a named unresolved ambiguity, rather than a mandatory detailed release plan for every requirement.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1350,
          "quote": "intent\n  -> requirement\n  -> build\n  -> assurance\n  -> release\n  -> deployment\n  -> live usage\n  -> observed telemetry\n  -> retirement",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FOperational%20Lifecycle%20Sufficiency%20Rule",
          "start_line": 1342
        }
      ],
      "key": "operational_lifecycle",
      "label": "Operational lifecycle sufficiency"
    },
    {
      "conditions": [],
      "definition": "Universal Intake Triage is the single entry route for substantive change, regardless of report label. It diagnoses the affected relation and selects a lawful change class and re-entry scope. The minimum classes are goal_reprice, intent_reprice, product_reprice, requirement_reprice, design_reframe and realization_refactor. Classification is separate from authority to mutate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1390,
          "quote": "There is one front door for substantive change.\n\nThe intake label does not determine the process class.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FUniversal%20Intake%20Triage",
          "start_line": 1388
        }
      ],
      "key": "intake_triage",
      "label": "Universal intake and change classes"
    },
    {
      "conditions": [
        "Assurance or intake requires causal diagnosis of a counterexample on a declared path."
      ],
      "definition": "Counterexample Localization identifies the earliest supported causal frontier: causally minimal violated owner relations or seam coordinates under the declared causal relation, not log or clock order. Its mutually distinguished forms are a unique violated locus, a jointly necessary set of incomparable earliest loci, unresolved alternative frontiers, or indeterminate bounded localization.",
      "exceptions": [
        "It does not add a separate pass to every change."
      ],
      "grounding": [
        {
          "end_line": 1493,
          "quote": "A testing counterexample is returned to its earliest supported causal frontier\non the declared path. The frontier contains the causally minimal violated owner\nrelations or seam coordinates established by the evidence; earliest means\nminimal under the declared causal relation, not first in log or clock order.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FCounterexample%20Localization",
          "start_line": 1490
        }
      ],
      "key": "causal_localization",
      "label": "Counterexample localization"
    },
    {
      "conditions": [],
      "definition": "Computed classification is a reusable intake result. C denotes reproducible facts and declared rule application; J denotes residual semantic/materiality judgment; O denotes a ruling reserved to its actual owner. Its four reported dimensions are authority traversal, Public delta, accepted-design coverage and rule-determined treatment. These annotations introduce no calculus kind, runtime, classifier interface, mandatory document or authority.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1538,
          "quote": "`C` denotes reproducible facts and declared\nrule application; `J` denotes residual semantic or materiality judgment; `O`\ndenotes a ruling reserved to its actual owner. These annotations grant no\nauthority and introduce no calculus kind, runtime, classifier interface, or\nmandatory document.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FChange%20Management%20Rule%2FComputed%20Classification%20And%20Treatment",
          "start_line": 1534
        }
      ],
      "key": "computed_classification",
      "label": "Computed classification and treatment"
    },
    {
      "conditions": [],
      "definition": "A consistency gate evaluates closure of a declared change span as a conjunction of all applicable obligations and required judgments or rulings, with no active non-closure condition. Closure is a separate predicate from the fitness of a local artifact.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1633,
          "quote": "Closure of a declared change span applies\n[Contract application](TRANSFORMATION_LIBRARY.md#contract-application) to reliance\non its closure evidence, then evaluates the conjunction of all applicable\nobligations and required judgments or rulings, with no active non-closure\ncondition.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FConsistency%20Gate%20Rule",
          "start_line": 1629
        }
      ],
      "key": "consistency_gate",
      "label": "Consistency and closure conjunction"
    },
    {
      "conditions": [],
      "definition": "UP-013 binds a Product-outcome-bearing work wave to one explicitly selected unresolved, directly verifiable Product-defined outcome instance and its declared acceptance interval. Material advance, prerequisite readiness, preservation and regression are progress annotations on results. Named bounded prerequisites enable Product obligations; named bounded experiments discriminate stated decisions through stated observations. Outcome meaning belongs to the Product owner; admission bases belong to work-wave authority or its explicitly bounded proxy.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1667,
          "quote": "Every Product-outcome-bearing work wave identifies one explicitly selected,\nunresolved, directly verifiable Product-defined outcome and declares the\nacceptance interval for that instance. Product-progress claims and promotion\nonto the supported Product path are judged against that same outcome.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FProduct%20Outcome%20Conservation%20%28%60STDO-UP-013%60%29",
          "start_line": 1664
        }
      ],
      "key": "product_outcome",
      "label": "Product outcome, prerequisites and experiments"
    },
    {
      "conditions": [],
      "definition": "UP-014 proportionality relates semantic ambiguity removed to effective reasoning complexity introduced. Complexity includes independent concepts and authority surfaces, cross-document joins, exceptions, branches, states, transitions, duplicated representations and decision detail; it is not raw line/artifact count or context-window size. Delivery priority applies this relation to the current outcome, likelihood, impact, reversibility, dependency and feedback-delay cost.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1756,
          "quote": "Proportionality is the relation between semantic ambiguity removed and\neffective reasoning complexity introduced. A method obligation is proportional\nwhen its contraction of the admissible interpretation space justifies the\nadditional concepts, relations, projections, and evidence that an agent must\nhold together to reach a correct decision.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FProportional%20Method%20And%20Delivery%20%28%60STDO-UP-014%60%29",
          "start_line": 1752
        }
      ],
      "key": "method_proportionality",
      "label": "Proportional method and delivery"
    },
    {
      "conditions": [
        "A selected outcome, delegated affected cone, concrete execution binding and separately bound assessment and decision authority."
      ],
      "definition": "UP-020 describes outcome-driven construction under an accepted basis: bounded affected relations → selected computational relations → delegated execution and decision authority → construction/self-review → independent live assessment where required → accept/local repair/re-enter/reject → exact accepted checkpoint → next already-authorized bounded action. Constructor, assessor and bounded decision proxy are distinct responsibilities; candidate existence, cone preservation and applied acceptance are distinct claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1859,
          "quote": "accepted governing basis\n  -> bounded affected relation set\n  -> selected computational relations\n  -> delegated execution and decision authority\n  -> construction and self-review\n  -> independent live-surface assessment where required\n  -> accept | local repair | re-enter | reject\n  -> exact accepted checkpoint\n  -> next already-authorized bounded action",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29",
          "start_line": 1851
        }
      ],
      "key": "agentic_construction",
      "label": "Agentic construction execution"
    },
    {
      "conditions": [],
      "definition": "The bounded causal construction unit is the smallest coherent causal dependency cone capable of delivering selected behavior while preserving every affected governing relation. Its seams follow support dependencies rather than function, file, module, ticket or document boundaries.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1890,
          "quote": "the\nsmallest coherent causal dependency cone capable of delivering the selected\nbehavior while preserving every affected governing relation. Its material seams\nfollow that condition, not function, file, module, ticket or document boundaries.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29%2FBounded%20Causal%20Construction",
          "start_line": 1887
        }
      ],
      "key": "causal_construction_cone",
      "label": "Bounded causal construction cone"
    },
    {
      "conditions": [],
      "definition": "Construction assessment tests whether the exact candidate closes its declared cone and preserves every affected governing relation. It returns evidence and a proposed semantic disposition. Applying the disposition is a separate decision on exact subject, basis and mandate. Acceptance binds an exact checkpoint; preservation checkpoints can retain unfinished or unaccepted work without acceptance, promotion or publication. Churn is rejected or superseded construction recorded as history/cost.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 1940,
          "quote": "Assessment evaluates the exact predicate `the candidate closes its declared\ncone and preserves every affected governing relation` through the shared\n[result algebra](FOUNDATIONS.md#result-algebra). It returns evidence and a\nproposed semantic disposition. Apply [Dispose](TRANSFORMATION_LIBRARY.md#dispose)\nto the separate decision on that proposal, using this section's construction\nconditions and the existing authority's bound mandate.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29%2FProportional%20Disposition",
          "start_line": 1935
        },
        {
          "end_line": 2022,
          "quote": "A preservation checkpoint may retain unfinished or unaccepted work under an\nexisting exact operation grant. Identify its parent or predecessor, included\nterritory, concurrent-writer disposition and durable evidence location. It is\nneither acceptance, promotion nor publication.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FAgentic%20Construction%20Execution%20%28%60STDO-UP-020%60%29%2FCheckpoint%2C%20Continuation%2C%20Progress%2C%20And%20Churn",
          "start_line": 2019
        }
      ],
      "key": "construction_disposition",
      "label": "Construction disposition and checkpoints"
    },
    {
      "conditions": [
        "A consequential transition with actual admission owners."
      ],
      "definition": "UP-021 complete enclosing-relation admission concerns the exact complete material transition, including every participant and equality join whose identity, validity, authority, currentness or transition can affect or be affected by admission. It distinguishes admission assessment, authorized admission/refusal/effect-free-re-entry decision, actual semantic commit, atomicity, form applicability and observed effects. Design declares supported direct/composite/nested forms and coherent composite bases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2067,
          "quote": "Its support universe is\nevery participant and equality join whose identity, validity, authority,\ncurrentness or transition can affect or be affected by admission. The owner\nindependently derives and validates that relation from authoritative inputs;\nthe shared Support condition governs crossing seams and independence claims.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FComplete%20Enclosing-Relation%20Admission%20%28%60STDO-UP-021%60%29",
          "start_line": 2063
        }
      ],
      "key": "complete_transition_admission",
      "label": "Complete enclosing-relation admission"
    },
    {
      "conditions": [],
      "definition": "A core interface is a shared contract or carrier materially governing runtime closure, reporting/status truth, topology/frame progression, proof/qualification, event/projection semantics, identity/binding resolution or provider/resolver behavior. A change that can alter how multiple surfaces determine current truth is a core interface change.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2308,
          "quote": "If changing the interface can alter how multiple surfaces decide \"what is true\nnow,\" it is a core interface change.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FCore%20Interface%20Migration%20Rule%2FWhat%20Counts%20As%20A%20Core%20Interface",
          "start_line": 2307
        }
      ],
      "key": "core_interface",
      "label": "Core interface"
    },
    {
      "conditions": [],
      "definition": "Constitutional migration replaces a load-bearing shared interface. Inside-Out Hard-Break Migration replaces source truth in place on the same implementation line through deliberate breaks and outward repairs. Fundamental Re-Adoption Migration intentionally re-derives on a materially different implementation basis and moves the predecessor sideways as reference material. The affected acceptance path is the outcome's full causal closure; Product-slice promotion and complete migration closure are separate claims.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2232,
          "quote": "- **Inside-Out Hard-Break Migration**: use this when the project remains on the\n  same implementation line and the authoritative source truth is being replaced\n  in place. The work proceeds from source carrier outward through a sequence of\n  deliberate breaks and repairs.\n- **Fundamental Re-Adoption Migration**: use this when the rewrite is major and\n  the project is intentionally re-deriving itself on a materially different\n  implementation basis, such as a new runtime model, carrier model, type\n  system, execution substrate, or realization tree. The prior implementation is\n  moved sideways and treated as reference material, not live authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FCore%20Interface%20Migration%20Rule%2FConstitutional%20Migration%20Options",
          "start_line": 2224
        }
      ],
      "key": "constitutional_migration",
      "label": "Constitutional migration and its strategies"
    },
    {
      "conditions": [],
      "definition": "A proof target binds an exact subject, intended property and governing basis to a witness, the nearest weaker excluded property and a falsification condition. Semantic basis comprises constitutional and accepted-design meaning; evidence basis comprises exact artifacts, events, logs, tests and observations; state projection is a current view derived from admitted semantic and evidence bases.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2500,
          "quote": "Before selecting that witness, bind its relation to the claim, the nearest\nweaker excluded property and the falsification condition. Missing these\nrelations leaves evidence discovery, not closure-grade proof.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FProof%20Target%20Identity%20And%20Adequacy%20%28%60STDO-UP-001%60%29",
          "start_line": 2498
        },
        {
          "end_line": 2521,
          "quote": "- **semantic basis**: constitutional and accepted-design relations defining\n  what a claim means;\n- **evidence basis**: exact artifacts, events, logs, tests, and observations\n  used to evaluate it; and\n- **state projection**: a current view derived from admitted semantic and\n  evidence bases.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FSemantic%2C%20Evidence%2C%20And%20Projection%20Separation%20%28%60STDO-UP-008%60%29",
          "start_line": 2516
        }
      ],
      "key": "proof_target",
      "label": "Proof target and semantic/evidence/projection bases"
    },
    {
      "conditions": [],
      "definition": "UP-022 assurance-boundary congruence relates checker, validator, harness or review evidence to the authoritative composite subject and claimed promotion/closure predicate. Generic method qualification uses a fresh competent constructor within a declared capability/context/configuration envelope, ordinary method and authority surfaces, a frozen result, and an independently authorized evaluator with declared basis and comparison predicate.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2536,
          "quote": "Its support boundary is the authoritative composite subject;\nsingle-carrier evidence leaves unexamined cross-carrier obligations open.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FEvidence%20Rules%2FAssurance-Boundary%20Congruence%20And%20Method%20Qualification%20%28%60STDO-UP-022%60%29",
          "start_line": 2535
        }
      ],
      "key": "assurance_qualification",
      "label": "Assurance congruence and method qualification"
    },
    {
      "conditions": [],
      "definition": "Scenarios are Product-owner concrete end-to-end use cases testing operational meaning from intent to realized behavior. Scenario bundles or equivalent ordered testcase sets make feature boundaries, significant sequences and expected intermediate outcomes inspectable. Requirements preserve invariant truth, Design structural choice, and Scenarios operational meaning; these are distinct verification roles.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2636,
          "quote": "Scenarios are the product-owner layer. They are concrete, end-to-end use cases\nthat test the chain from intent to realized behavior. Without an adequate\nscenario, that layer has not demonstrated the capability.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FVerification%20Layers",
          "start_line": 2634
        }
      ],
      "key": "operational_scenarios",
      "label": "Scenarios and scenario bundles"
    },
    {
      "conditions": [],
      "definition": "The Product-level test-authority taxonomy belongs to urn:stdo:bounded-context:product-assurance. Design/module conformance tests derive from realization authority and include unit tests and appropriately targeted module integration, negative and fail-closed tests. UAT/acceptance tests derive from constitutional Product/user authority and exercise an isolated composed Product. Harnessed sandbox UAT uses deterministic, fake, recorded or injected workers/results; live sandbox UAT crosses a real configured external worker/tool/agent/service/transport boundary. Authority source is distinct from execution breadth.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2685,
          "quote": "Authority source is not the same thing as execution breadth. A test may be\nsmall or broad, fast or slow, deterministic or live, but it still derives from\none of two primary authorities:\n\n1. **Design/module conformance tests**\n2. **UAT / acceptance tests**",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FTesting%20Strategy%20Taxonomy",
          "start_line": 2680
        }
      ],
      "key": "test_authority_taxonomy",
      "label": "Test authority and execution lanes"
    },
    {
      "conditions": [],
      "definition": "Requirement families describe four kinds of constitutional truth: Capability supplies behavior/function/surface; Constraint/Guarantee bounds behavior through invariants, laws, safety, portability or semantic guarantees; Governance controls lifecycle, authority, visibility, release or operator action; Verification requires tests, evidence, traceability, qualification or forensic surfaces. Categories identify truth ownership, not priority or user-facing status.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2873,
          "quote": "| **Capability** | A behavior, function, or surface the system must provide | \"What can the system do?\" |\n| **Constraint / Guarantee** | An invariant, law, safety property, portability rule, or semantic guarantee that bounds how the system may behave | \"What must always remain true?\" |\n| **Governance** | A policy or control rule over lifecycle, authority, visibility, release, or operator action | \"What governs use and change?\" |\n| **Verification** | A requirement on tests, evidence, traceability, qualification, or forensic surfaces | \"How do we know the claim is true?\" |",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FRequirement%20Categories",
          "start_line": 2870
        }
      ],
      "key": "requirement_categories",
      "label": "Requirement categories"
    },
    {
      "conditions": [],
      "definition": "The Reconstruction Litmus tests whether a competent team can derive conformant Intent from Goals, Product from Intent, Requirements from Product, Design from Requirements, and Realization from Requirements plus Design in the selected environment. It tests sufficiency and reconstructable routes, not unique derivation, determinism or repeated reconstruction at every use.",
      "exceptions": [],
      "grounding": [
        {
          "end_line": 2901,
          "quote": "This does not mean the derivation is unique. Different designs may satisfy the\nsame requirements, and different software, human or mixed realizations may\nsatisfy the same design. The test is sufficiency, not determinism.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FReconstruction%20Litmus",
          "start_line": 2899
        }
      ],
      "key": "reconstruction_litmus",
      "label": "Reconstruction sufficiency"
    }
  ],
  "constraints": [
    {
      "applies_to_keys": ["project_reference_frame_basis", "agent_frame_activation"],
