      "exceptions": [],
      "grounding": [
        {
          "end_line": 859,
          "quote": "Profile availability, Product adoption, and execution-scoped activation are\nthree distinct relations. Inclusion in a selected method cut makes a profile\navailable. Only Product authority may adopt it. Only an exact authorized work\ninstruction may activate one bound frame for an actor and subject.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 856
        }
      ],
      "key": "frame_basis_ownership_and_activation",
      "statement": "REFERENCE_FRAME_METHOD supplies principles and STDO_REFERENCE_FRAME_BASELINE one optional profile; neither selects, adopts or owns Product bindings. Existing Product authority owns the concrete declaration and every grant. reference_frame_bases is non-empty; every entry locates one accepted declaration, every admitting Goals/Product/requirement/accepted-design/other lawful authority, and its exact governed Product/context/tenant/outcome/other scope. The declaration owns selected frames, method/profile, outcome, actor rules, envelopes, grant requirements, triggers, coverage, result relations and invalidation; the locator neither contains/adopts/restates the binding nor creates authority. Availability, adoption and authorized activation are distinct. Activation does not mutate the overlay; the overlay neither registers agents, permanently assigns frames nor persists temporary configurations. Actor names and broad frames grant no semantic, operational, review, acceptance or disposition authority beyond cited owners and exact activation.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["project_reference_frame_basis"],
      "conditions": [
