      "exceptions": [],
      "grounding": [
        {
          "end_line": 885,
          "quote": "Every directed Product-composition edge names its\nsource and target roles, governing authority and contracts, lifecycle,\nevidence boundary, refusal, and invalidation conditions. Common actors,\nrepositories, files, implementations, outputs, or tool access create no\ncomposition or identity relation.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 881
        }
      ],
      "key": "frame_product_role_map",
      "statement": "The basis records a Product-role map keeping mutable Source Projects, Product Definitions, candidate checkpoints, Release Cuts, released Products, Installs, Artifacts and dependent Products distinct. Each Development Product is a role binding over its exact underlying Install. Every directed composition edge names source/target roles, governing authority/contracts, lifecycle, evidence boundary, refusal and invalidation conditions. Shared actors, repositories, files, implementations, outputs or tools establish neither composition nor identity.",
      "uncertainty": ""
    },
    {
      "applies_to_keys": ["project_reference_frame_basis"],
      "conditions": [],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 900,
          "quote": "A Product, domain, or runtime carrier also named `Frame` is not included by\nnominal match. It remains governed by its bound `WHAT` and `HOW` and may be the\nsubject or coordinate of an evaluation frame. It enters the collective frame\nset only through an explicit frame declaration with the required evaluation\nand authority relations.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 896
        },
        {
          "end_line": 894,
          "quote": "An adopting Product replaces every placeholder with its own\nexact identities, owners, scopes, sources, grants, results, and invalidation\nconditions, then admits that completed declaration under existing authority.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FCollective%20Reference-Frame%20Basis",
          "start_line": 892
        }
      ],
      "key": "frame_template_and_nominal_exclusion",
      "statement": "The copyable PROJECT_REFERENCE_FRAME_BASIS_TEMPLATE is not authority; adoption replaces every placeholder with exact Product identities, owners, scopes, sources, grants, results and invalidators, then admits the declaration under existing authority. No schema, axiomatic representation, prompt framework or runtime frame engine is required. A Product/domain/runtime carrier named Frame remains governed by its WHAT/HOW and may be an evaluation subject or coordinate; name matching does not enroll it. Enrollment requires an explicit declaration with required evaluation and authority relations.",
