      "conditions": [],
      "exceptions": [],
      "grounding": [
        {
          "end_line": 964,
          "quote": "Goals own the\nbounded work wave, ticket state remains ticket authority, and comments remain\nnon-authoritative commentary.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FWHAT%2C%20HOW%2C%20And%20Work%20Carriers",
          "start_line": 962
        }
      ],
      "key": "what_how_work_locator_roles",
      "statement": "what.intent and what.product each locate one canonical constitutional entrypoint; what.specification may locate multiple requirement/specification surfaces. Each canonical how.build_tenants entry has stable identity and root/design/implementation locators. how.common binds a realization law explicitly adopted across more than one tenant. A separate TENANT_REGISTRY.md may be a human companion or generated projection, never a second identity/location authority. ticketing.goals locates the current wave; ticketing.tickets the durable root and at least backlog/active/completed lanes; ticketing.comments the commentary root; ticketing.sprints optionally bounded batch manifests. Goals, ticket-state authority and non-authoritative commentary retain distinct roles.",
      "uncertainty": ""
