      "exceptions": [],
      "grounding": [
        {
          "end_line": 990,
          "quote": "Resolution verifies both locator and expected identity. Moving a definition\nrequires a locator update but does not change its identity. Replacing content\nat the same locator with another definition identity fails closed. When an edge\nbinds exact immutable Product or release versions, the cited relation and\ncontracts also carry and verify those identities; the mutable definition\nidentity cannot substitute for them.",
          "section_id": "repo://stdo-v3-generation/codex/5a5b5ad80f0ba4b56b83aadd42ac130de53ba803/source/standards/SPEC_METHOD.md#Spec-Driven%20Homeostatic%20Methodology%2FSTDO%20Product%20Definition%20Overlay%20And%20Layout%20Independence%2FRecursive%20Discovery%20And%20Explicit%20Composition",
          "start_line": 985
        }
      ],
      "key": "definition_composition_identity",
      "statement": "Directory nesting creates no inheritance, ownership, composition or constitutional override. Each explicit composition entry records product_definition locator, target_definition_id expected from product.definition_id, relation authority defining directed kind/roles/owner/scope/lifecycle/invalidators, and one or more exact consumed governing contracts. Resolution verifies locator and identity; moves require locator updates without identity change; replacement identity at an unchanged locator fails closed. Exact immutable Product/release identities, when bound, must also be carried and verified by relation/contracts and cannot be replaced by mutable definition identity.",
      "uncertainty": ""
